{"results": [{"id": "hp_doc_3b4a8afa14195a97b068e64ddd4260f21f03d8db58d2274e7f103da1de3226da", "title": "1976 German Grand Prix", "text": "The 1976 German Grand Prix (formally the XXXVIII Großer Preis von Deutschland) was a Formula One motor race held at the Nürburgring on 1 August 1976. It was the scene of reigning world champion Niki Lauda's near fatal accident, and the last Formula One race to be held on the Nordschleife section of the track. The 14-lap race was the tenth round of the 1976 Formula One season and was won by James Hunt.", "score": 25.2335}, {"id": "hp_doc_845b7271c24a5e29f3f498576f096c78a8ac8fd94c15310018d18003aab03c2a", "title": "1977 German Grand Prix", "text": "The 1977 German Grand Prix was a Formula One motor race held at Hockenheimring on July 31, 1977. After Niki Lauda's near-fatal accident at the dangerous Nürburgring in 1976, the German Grand Prix was moved to Hockenheim and was held there every year except for one until 2007, and this was the second year the race was held there (the first being 1970).", "score": 23.1024}, {"id": "hp_doc_8cf31b4584addd39a87257c3e002ce4a7ca7b879323219f80c142592b338c60a", "title": "1984 European Grand Prix", "text": "The 1984 European Grand Prix was a Formula One motor race held at Nürburgring on 7 October 1984. It was the fifteenth round of the 1984 Formula One season. This was the first time a Formula One race was run on the new 4.54 km (2.82 mi) Nürburgring GP-Strecke and the first time F1 had returned to the 'Ring since the 1976 German Grand Prix that was held on the old 22.835 km (14.19 mi) Nordschleife circuit.", "score": 18.996}], "remaining_searches": 2}
